    for(int mode:{metro::MxModClocks,metro::MxModStageNum}){m->params[M::MX_MODE].setValue(mode);m->params[M::MOD_GROUP_MUTE].setValue(0);m->readSettings();mxEdge();bool active=false;for(auto& out:child.outputs)active|=out.getVoltage()==5;require(active,"actual reciprocal MX MOD output active before group mute");m->params[M::MOD_GROUP_MUTE].setValue(1);m->readSettings();mxEdge();for(auto& out:child.outputs)require(out.getVoltage()==0,"actual MX MOD clocks and stage gates respect group mute");m->params[M::MOD_GROUP_MUTE].setValue(0);m->readSettings();mxEdge();active=false;for(auto& out:child.outputs)active|=out.getVoltage()==5;require(active && mask(*m)==12,"MX group unmute resumes current phase and preserves lane mask");}
