    m->params[M::MOD_GROUP_MUTE].setValue(1);auto saved=m->capturePreset();require(M::presetIndex(M::MOD_GROUP_MUTE)==521 && saved.values[521]==1,"preset appends group state after every frozen format10 value");m->putPreset(0,saved);m->params[M::MOD_GROUP_MUTE].setValue(0);m->params[M::modParam(2,M::MOD_MUTE)].setValue(0);clearReceipts(*m);m->requestPreset(0);m->sendPresetCommand();frames(*m);require(m->integer(M::MOD_GROUP_MUTE)==1 && mask(*m)==12,"ordinary preset recall restores both independent layers");
