    m->params[M::INIT_PRESET].setValue(1);m->params[M::MOD_GROUP_MUTE].setValue(0);m->requestInitialize();m->sendPresetCommand();frames(*m);require(m->integer(M::MOD_GROUP_MUTE)==1,"custom Init recalls group mute");
    Json module(APP->engine->moduleToJson(m.get()));std::string error;Scope scope;
    for(int format=1;format<=10;++format){Json old(capture(module.get(),Presets));old.reset(json_deep_copy(old.get()));auto* bank=json_object_get(old.get(),"bank");json_object_set_new(bank,"presetFormat",json_integer(format));auto* values=json_array_get(json_object_get(bank,"presets"),0);while(json_array_size(values)>size_t(M::presetSize(format)))json_array_remove(values,json_array_size(values)-1);other->params[M::MOD_GROUP_MUTE].setValue(1);Json before,after;require(restore(other.get(),old.get(),before,after,error),"every older full musical bank migrates through strict restore");auto loaded=other->getPreset(0);require(loaded.occupied && loaded.values[521]==0 && other->integer(M::MOD_GROUP_MUTE)==1,"old stored group defaults Off while live group remains unchanged");for(int l=0;l<8;++l)require(loaded.values[M::presetIndex(M::modParam(l,M::MOD_MUTE))]==float((12>>l)&1),"migration retains exactly the old individual lane mask");}
